72: /// ```
73: /// use flightreader_core::dat::checksum::{calc_crc16_ccitt, CRC16_INIT_PRIMARY};
74: ///
75: /// let header_and_payload = [0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00];
