13: /// Constructs a synthetic `.txt` log header for testing.
14: fn make_header(
15:     details_offset: i64,
16:     header_length: i16,
17:     version: u8,
18:     department: u8,
19:     scrambled_flag: u8,
20:     padding: Option<u8>,
21:     reserved_fill: Option<u8>,
22: ) -> Vec<u8> {
23:     let total_len = if padding.is_some() || header_length == 101 {
24:         101
25:     } else {
26:         100
27:     };
28:     let mut buf = vec![0u8; total_len];
29:     LittleEndian::write_i64(&mut buf[0..8], details_offset);
30:     LittleEndian::write_i16(&mut buf[8..10], header_length);
31:     buf[10] = version;
32:     buf[11] = department;
33:     buf[12] = scrambled_flag;
34: 
35:     if let Some(fill) = reserved_fill {
36:         buf[13..100].fill(fill);
37:     }
38: 
39:     if let Some(pad) = padding {
40:         buf[100] = pad;
41:     }
42: 
43:     buf
44: }
